type Constructor<T> = new (...args: any[]) => T;

class Container {
  private services = new Map();

  register<T>(key: string, value: Constructor<T>) {
    this.services.set(key, value);
  }

  resolve<T>(key: string): T {
    const Service = this.services.get(key);
    return new Service();
  }
}

class Logger {
  log(msg: string) {
    console.log(msg);
  }
}

const container = new Container();
container.register('logger', Logger);

const logger = container.resolve<Logger>('logger');
logger.log('DI working');

type PluginAPI = {
  log: (msg: string) => void;
};

type Plugin = (api: PluginAPI) => void;

class Runtime {
  private plugins: Plugin[] = [];

  register(plugin: Plugin) {
    this.plugins.push(plugin);
  }

  run() {
    const api: PluginAPI = {
      log: console.log
    };

    this.plugins.forEach(p => p(api));
  }
}

const runtime = new Runtime();

runtime.register((api) => {
  api.log('Plugin executed');
});

runtime.run();

type Event =
  | { type: 'created'; payload: { id: number } }
  | { type: 'updated'; payload: { id: number; value: string } };

class EventStore {
  private events: Event[] = [];

  append(event: Event) {
    this.events.push(event);
  }

  getAll() {
    return this.events;
  }
}

const store = new EventStore();

store.append({ type: 'created', payload: { id: 1 } });
store.append({ type: 'updated', payload: { id: 1, value: 'ok' } });

console.log(store.getAll());

class QueryBuilder {
  private query = '';

  select(fields: string) {
    this.query += `SELECT ${fields} `;
    return this;
  }

  from(table: string) {
    this.query += `FROM ${table} `;
    return this;
  }

  where(condition: string) {
    this.query += `WHERE ${condition} `;
    return this;
  }

  build() {
    return this.query;
  }
}

const query = new QueryBuilder()
  .select('*')
  .from('users')
  .where('id = 1')
  .build();

console.log(query);

type Task = {
  id: string;
  payload: unknown;
};

class Scheduler {
  private queue: Task[] = [];

  add(task: Task) {
    this.queue.push(task);
  }

  run() {
    this.queue.forEach(task => {
      console.log('Executing task', task.id);
    });
  }
}

const scheduler = new Scheduler();

scheduler.add({ id: 'task-1', payload: {} });

scheduler.run();
